head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
scwin.fn_GetPar, scwin.fn_SetPar, scwin.strCdSch, scwin.queryId, scwin.gubun;
scwin.fr_SecuGrpId; // 증권그룹ID
scwin.fr_MktId = $c.lcd.fn_getMktId();
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; // 시장구분코드(유가, 코스닥) 전체), 기준은 로그인 사용자의 부서 소속을 기준으로 한다.

scwin.fn_list_sync = function() {
    $c.cm.ShowWin(grd);
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=DIGITAL_ADMISU_ISU_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=" + scwin.queryId + "&{P}param01=" + txb_Search.getValue();
    dts.DataID = encodeURI(url);
    dts.reset();
};
scwin.setColumnName = function() {
    if (scwin.gubun == "B") {
        $c.cm.setColumnProp(grd, 'ISUR_CD', 'Name', "신탁기관코드");
        $c.cm.setColumnProp(grd, 'ISUR_NM', 'Name', "신탁기관명");
        label_1.setValue("신탁기관명");
    }
};
scwin.txb_Search_onkeydown = function() {
    if (event.keyCode == 13) {
        scwin.fn_list_sync();
    }
};
scwin.dts_OnLoadError = function() {
    $c.stf.alert_error(dts);
};
scwin.dts_OnLoadCompleted = function(rowcount) {
    if (dts.errorMsg) {
        $c.win.alert(dts.errorMsg);
    } else {
        txb_TotCnt.setValue("총 " + rowcount + " 건");

        // 초기1회 초기값으로 설정된 회사코드를 검색한다.
        if (scwin.strCdSch != "") {
            for (var i = 1; i <= dts.getTotalRow(); i++) {
                if (scwin.strCdSch == dts.getCellData(i, 1)) {
                    dts.setRowPosition(i, 0);
                    break;
                }
            }
            scwin.strCdSch = "";
        }
        $c.cm.CloseWin(rowcount, grd);
    }
};
scwin.grd_OnDblClick = async function(row, colid) {
    var arrPar = new Array();
    if (scwin.fn_SetPar != undefined) {
        arrPar[0] = {
            ISUR_CD: dts.getCellData(dts.getRowPosition(), "ISUR_CD"),
            ISUR_NM: dts.getCellData(dts.getRowPosition(), "ISUR_NM"),
            DBCLICKYN: "Y"
        };
        scwin.fn_SetPar(arrPar);
    }
    await $c.frame.CloseFrame();
};
scwin.img_Search_onclick = function() {
    scwin.fn_list_sync();
};
scwin.img_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    window.document.body.scroll = "no";
    var arrPar = new Array();
    /***************************************
    opener에  fn_GetPar의 이름을 가진 함수가 있다면, 이 펑션에 인수를 넘겨 값을 채워 이용한다. 없다면 업종조회후  최초 지정 코드값이 없는 상태
    opener에  fn_SetPar의 이름을 가진 함수가 있다면, 이 펑션에 인수를 넘겨 값을 채워 이용한다. 없다면 선택한 코드값과 코드명칭을 지정하지 않는다.
    ***************************************/
    var parentWin = $c.frame.path("../");
    scwin.fn_GetPar = parentWin.scwin.fn_GetPar;
    scwin.fn_SetPar = parentWin.scwin.fn_SetPar;
    if (scwin.fn_GetPar != undefined) {
        scwin.fn_GetPar(arrPar);
        scwin.queryId = (arrPar.length >= 1 ? arrPar[0] : "");
        scwin.gubun = (arrPar.length >= 2 ? arrPar[1] : "");
    }
    scwin.setColumnName();
    txb_Search.focus();
    scwin.fn_list_sync();
};
